mapper.select:
select * from ( select t.id, t.card_id, t.bank_card_id, t.bank_card_name, t.transaction_date, t.bookkeeping_date, t.transaction_desc, t.balance_currency, t.balance_money, t.card_type_id, t.card_type_name, t.consumption_type, t.consume_id, t.consume_code, t.consume_name, t.memo, t.statement_id, t.income_money, t.opponent_account, t.opponent_name, t.transaction_time, t.account_balance, t.txn_kind, coalesce(nullif(trim(bc.bank_code), ''), nullif(trim(st.source_bank_code), '')) as bank_code, bc.card_type_code, sem.economic_nature as sem_economic_nature, sem.budget_behavior as sem_budget_behavior, sem.report_role as sem_report_role, sem.quality_state as sem_quality_state, sem.include_in_income_trend as sem_include_in_income_trend, sem.include_in_expense_trend as sem_include_in_expense_trend, sem.include_in_budget as sem_include_in_budget, coalesce(cat.parent_id, sem.category_l1_code) as category_parent_id, cat.semantic_tag as category_semantic_tag, sem.category_l1_name as category_l1_name from transaction t left join fin_bank_account bc on bc.id = t.bank_card_id and (bc.deleted is null or bc.deleted != 1) left join statement st on st.id = t.statement_id and (st.deleted is null or st.deleted != 1) left join cls_category cat on cat.code = coalesce(nullif(trim(t.consume_code), ''), nullif(trim(t.category_code), '')) and cat.deleted != 1 left join v_transaction_finance_semantics sem on sem.id = t.id where 1 = 1
and t.transaction_date >= #{q.transactionDateStart,jdbcType=DATE}
and t.transaction_date <= #{q.transactionDateEnd,jdbcType=DATE}
and t.consumption_type = #{q.consumptionType,jdbcType=NUMERIC}
and t.card_type_name = #{q.cardTypeName,jdbcType=VARCHAR}
and (t.consume_id = #{q.consumeID,jdbcType=VARCHAR} or t.category_id = #{q.consumeID,jdbcType=VARCHAR})
and (t.consume_code = #{q.consumeCode,jdbcType=VARCHAR} or t.category_code = #{q.consumeCode,jdbcType=VARCHAR})
and ( t.consume_name is null or length(trim(t.consume_name)) = 0 or t.consume_code is null or length(trim(t.consume_code)) = 0 or t.category_name is null or length(trim(t.category_name)) = 0 or t.category_code is null or length(trim(t.category_code)) = 0 )
and ( t.consume_name = #{q.consumeName,jdbcType=VARCHAR} or cat.name = #{q.consumeName,jdbcType=VARCHAR} or exists ( select 1 from cls_category parent where parent.deleted != 1 and parent.name = #{q.consumeName,jdbcType=VARCHAR} and ( cat.parent_id = parent.code or cat.parent_id = parent.id ) ) )
and ( t.memo like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') or t.transaction_desc like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') )
and weekday(t.bookkeeping_date) = #{q.weekName,jdbcType=VARCHAR}
and year(t.transaction_date) = #{q.year,jdbcType=VARCHAR}
and month(t.transaction_date) = #{q.month,jdbcType=VARCHAR}
) t limit #{page.recordBegin,jdbcType=NUMERIC}, #{page.pageSize,jdbcType=NUMERIC}

select count(distinct t.id) from transaction t
left join fin_bank_account bc on bc.id = t.bank_card_id and (bc.deleted is null or bc.deleted != 1)
left join statement st on st.id = t.statement_id and (st.deleted is null or st.deleted != 1)

where 1 = 1






