select round(sum(
)) as `value`, coalesce(nullif(trim(c.consume_code), ''), '__UNCLASSIFIED__') as code, coalesce(nullif(trim(cat.name), ''), nullif(trim(c.consume_name), ''), '未分类') as name, coalesce(nullif(trim(parent.code), ''), nullif(trim(cat.code), ''), '__UNCLASSIFIED__') as level1Code, coalesce(nullif(trim(parent.name), ''), nullif(trim(cat.name), ''), '未分类') as level1Name from transaction c left join statement st on st.id = c.statement_id and (st.deleted is null or st.deleted != 1) left join cls_category cat on cat.code = c.consume_code and cat.deleted != 1 left join cls_category parent on parent.id = cat.parent_id and parent.deleted != 1 where 1 = 1
and (c.txn_kind is null or c.txn_kind = '' or c.txn_kind != 'transfer')
and ( cat.txn_types like CONCAT('%', #{q.txnTypes,jdbcType=VARCHAR}, '%') or (cat.code is null and (
coalesce(c.balance_money,0) > 0
(coalesce(c.income_money,0) > 0 or coalesce(c.balance_money,0) < 0)
1 = 0
)) )
and ( cat.txn_types like '%expense%' or (cat.code is null and coalesce(c.balance_money,0) > 0) )
and c.transaction_date >= #{q.transactionDateStart,jdbcType=DATE}
and c.transaction_date <= #{q.transactionDateEnd,jdbcType=DATE}
and c.card_type_name = #{q.cardTypeName,jdbcType=VARCHAR}
and (c.memo like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') or c.transaction_desc like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') )
group by coalesce(nullif(trim(c.consume_code), ''), '__UNCLASSIFIED__'), coalesce(nullif(trim(cat.name), ''), nullif(trim(c.consume_name), ''), '未分类'), coalesce(nullif(trim(parent.code), ''), nullif(trim(cat.code), ''), '__UNCLASSIFIED__'), coalesce(nullif(trim(parent.name), ''), nullif(trim(cat.name), ''), '未分类') order by `value` desc

select round(sum(expense_amt)) as `value`, wday as `key` from ( select weekday(c.bookkeeping_date) wday, () as expense_amt from transaction c left join statement st on st.id = c.statement_id and (st.deleted is null or st.deleted != 1) left join cls_category cat on cat.code = c.consume_code and cat.deleted != 1 where 1 = 1
and cat.txn_types like CONCAT('%', #{q.txnTypes,jdbcType=VARCHAR}, '%')
and c.transaction_date >= #{q.transactionDateStart,jdbcType=DATE}
and c.transaction_date <= #{q.transactionDateEnd,jdbcType=DATE}
and c.card_type_name = #{q.cardTypeName,jdbcType=VARCHAR}
and (c.memo like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') or c.transaction_desc like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') )
) view1 group by wday order by wday

select round(abs(balance_money)) 'value', case when cmonth = 1 then 'January' when cmonth = 2 then 'February' when cmonth = 3 then 'March' when cmonth = 4 then 'April' when cmonth = 5 then 'May' when cmonth = 6 then 'June' when cmonth = 7 then 'July' when cmonth = 8 then 'August' when cmonth = 9 then 'September' when cmonth = 10 then 'October' when cmonth = 11 then 'November' when cmonth = 12 then 'December' else cmonth end 'key' from (select sum(expense_amt) balance_money,cmonth from (select () as expense_amt, month(c.transaction_date) cmonth from transaction c left join statement st on st.id = c.statement_id and (st.deleted is null or st.deleted != 1) left join cls_category cat on cat.code = c.consume_code and cat.deleted != 1 where 1 = 1
and cat.txn_types like CONCAT('%', #{q.txnTypes,jdbcType=VARCHAR}, '%')
and year(c.transaction_date) = #{q.year,jdbcType=VARCHAR}
and c.card_type_name = #{q.cardTypeName,jdbcType=VARCHAR}
and (c.memo like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') or c.transaction_desc like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') )
) t1 group by cmonth) t2 order by cmonth

select round(sum(amount)) as `value`, case when cmonth = 1 then 'January' when cmonth = 2 then 'February' when cmonth = 3 then 'March' when cmonth = 4 then 'April' when cmonth = 5 then 'May' when cmonth = 6 then 'June' when cmonth = 7 then 'July' when cmonth = 8 then 'August' when cmonth = 9 then 'September' when cmonth = 10 then 'October' when cmonth = 11 then 'November' when cmonth = 12 then 'December' else cmonth end as `key` from ( select month(c.transaction_date) as cmonth, case when (coalesce(c.income_money,0) > 0) then coalesce(c.income_money,0) when (coalesce(c.balance_money,0) < 0) then abs(coalesce(c.balance_money,0)) else 0 end as amount from transaction c left join statement st on st.id = c.statement_id and (st.deleted is null or st.deleted != 1) left join cls_category cat on cat.code = c.consume_code and cat.deleted != 1 where 1 = 1
and (c.txn_kind is null or c.txn_kind = '' or c.txn_kind != 'transfer')
and year(c.transaction_date) = #{q.year,jdbcType=VARCHAR}
and c.transaction_date >= #{q.transactionDateStart,jdbcType=DATE}
and c.transaction_date <= #{q.transactionDateEnd,jdbcType=DATE}
and c.card_type_name = #{q.cardTypeName,jdbcType=VARCHAR}
and (c.memo like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') or c.transaction_desc like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') )
and ( coalesce(c.income_money,0) > 0 or coalesce(c.balance_money,0) < 0 or (cat.txn_types is not null and cat.txn_types like '%income%') )
) t group by cmonth order by cmonth

select round(sum(amount)) as `value`, case when cmonth = 1 then 'January' when cmonth = 2 then 'February' when cmonth = 3 then 'March' when cmonth = 4 then 'April' when cmonth = 5 then 'May' when cmonth = 6 then 'June' when cmonth = 7 then 'July' when cmonth = 8 then 'August' when cmonth = 9 then 'September' when cmonth = 10 then 'October' when cmonth = 11 then 'November' when cmonth = 12 then 'December' else cmonth end as `key` from ( select month(c.transaction_date) as cmonth, case when (coalesce(c.balance_money,0) > 0) then coalesce(c.balance_money,0) else 0 end as amount from transaction c left join statement st on st.id = c.statement_id and (st.deleted is null or st.deleted != 1) left join cls_category cat on cat.code = c.consume_code and cat.deleted != 1 where 1 = 1
and (c.txn_kind is null or c.txn_kind = '' or c.txn_kind != 'transfer')
and year(c.transaction_date) = #{q.year,jdbcType=VARCHAR}
and c.transaction_date >= #{q.transactionDateStart,jdbcType=DATE}
and c.transaction_date <= #{q.transactionDateEnd,jdbcType=DATE}
and c.card_type_name = #{q.cardTypeName,jdbcType=VARCHAR}
and (c.memo like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') or c.transaction_desc like CONCAT('%', #{q.demoArea,jdbcType=VARCHAR}, '%') )
and (coalesce(c.balance_money,0) > 0 or (cat.txn_types is not null and cat.txn_types like '%expense%'))
) t group by cmonth order by cmonth

select round(coalesce(sum(), 0))
from transaction t
left join cls_category cat on cat.code = t.consume_code and cat.deleted != 1
where t.transaction_date >= #{start,jdbcType=DATE}
  and t.transaction_date <= #{end,jdbcType=DATE}


and (
    coalesce(t.income_money,0) > 0
    or coalesce(t.balance_money,0) < 0
    or (cat.txn_types is not null and cat.txn_types like '%income%')
)

select coalesce(nullif(trim(t.consume_code), ''), nullif(trim(t.category_code), ''), '__UNCLASSIFIED__') as code, coalesce(nullif(trim(cat.name), ''), nullif(trim(t.consume_name), ''), nullif(trim(t.category_name), ''), '未分类') as label, count(distinct t.id) as txnCount, round(sum()) as total from transaction t left join fin_bank_account bc on bc.id = t.bank_card_id and (bc.deleted is null or bc.deleted != 1) left join statement st on st.id = t.statement_id and (st.deleted is null or st.deleted != 1)
where 1 = 1
group by coalesce(nullif(trim(t.consume_code), ''), nullif(trim(t.category_code), ''), '__UNCLASSIFIED__'), coalesce(nullif(trim(cat.name), ''), nullif(trim(t.consume_name), ''), nullif(trim(t.category_name), ''), '未分类') order by total desc limit #{limit,jdbcType=NUMERIC}

select as token, coalesce(nullif(trim(t.opponent_name), ''), nullif(trim(t.transaction_desc), ''), 'Unknown') as label, count(distinct t.id) as txnCount, round(sum()) as total from transaction t left join fin_bank_account bc on bc.id = t.bank_card_id and (bc.deleted is null or bc.deleted != 1) left join statement st on st.id = t.statement_id and (st.deleted is null or st.deleted != 1)
where 1 = 1
group by , coalesce(nullif(trim(t.opponent_name), ''), nullif(trim(t.transaction_desc), ''), 'Unknown') having token is not null and trim(token) != '' order by total desc limit #{limit,jdbcType=NUMERIC}
